/* Traditional product-management demo. All edits are isolated to this browser. */
(() => {
  'use strict';
  const S=window.KairosStore;
  const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>'PKR '+Number(v).toLocaleString('en-PK',{maximumFractionDigits:2});
  const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',products:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 5v10l9 4 9-4V8M12 13v9M7 5l10 6"/>',categories:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><path d="M17.5 14v7M14 17.5h7"/>',orders:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Zm3 5h6M9 12h6"/>',settings:'<path d="M4 6h16M4 18h16M9 3v6m6 6v6M4 12h16"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6L16 3Zm-3 3 5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'};
  const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.products}</svg>`;
  let view='dashboard',search='',filter='',category='',draft=null,categoryDraft=null;
  const active=()=>['/preview-admin/','/admin/'].includes(location.pathname);
  const selected=(a,b)=>a===b?' selected':'';
  function notify(message){window.KairosUI?.toast(message);}
  function badge(status){return `<span class="a-badge ${status==='published'?'green':status==='draft'?'amber':'gray'}"><i></i>${E(status.charAt(0).toUpperCase()+status.slice(1))}</span>`;}
  function button(text,action,style=''){return `<button class="a-button ${style}" ${action}>${text}</button>`;}
  function metrics(){const p=S.state.products,orders=S.state.orders;return `<div class="a-metrics"><div><span>Total products ${icon('products')}</span><strong>${p.length}<small>timepieces</small></strong><p>${p.filter(p=>p.status==='published').length} published on your storefront</p></div><div><span>Local sample sales ${icon('orders')}</span><strong><small>PKR</small> ${orders.filter(o=>o.status!=='Cancelled').reduce((s,o)=>s+o.total,0)/100||0}</strong><p>From this browser’s sample checkouts</p></div><div><span>Categories ${icon('categories')}</span><strong>${S.state.categories.length}<small>collections</small></strong><p>Organised for effortless discovery</p></div><div><span>Low stock ${icon('dashboard')}</span><strong>${p.filter(p=>p.stock<=5).length}<small>products</small></strong><p>${p.filter(p=>p.stock===0).length} products currently out of stock</p></div></div>`;}
  function productRows(items){return items.length?items.map(p=>`<tr><td><div class="a-product-cell"><img src="${E(p.cover?.thumb||'/static/images/product-placeholder.svg')}" alt="" width="48" height="56"><div><button class="a-product-name" data-edit-product="${p.id}">${E(p.name)}</button><small>${E(p.sku)}</small></div></div></td><td><span class="a-cell-category">${E(p.collectionName)}</span></td><td><strong>${money(p.price)}</strong>${p.sale?`<del>${money(p.regularPrice)}</del>`:''}</td><td><span class="a-stock ${p.stock===0?'red':p.stock<=5?'amber':'green'}"><i></i>${p.stock===0?'Out of stock':p.stock+' available'}</span><small>${p.variants.length} variant${p.variants.length===1?'':'s'}</small></td><td>${badge(p.status)}</td><td><div class="a-row-actions"><button data-edit-product="${p.id}" aria-label="Edit ${E(p.name)}" title="Edit product">${icon('edit')}</button><button data-delete-product="${p.id}" aria-label="Delete ${E(p.name)}" title="Delete product">${icon('trash')}</button></div></td></tr>`).join(''):`<tr><td colspan="6"><div class="a-empty">${icon('products')}<h3>No products found.</h3><p>Add your first timepiece or change the filters.</p>${button('Add product','data-new-product')}</div></td></tr>`;}
  function table(items){return `<div class="a-table-scroll"><table class="a-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Inventory</th><th>Status</th><th>Actions</th></tr></thead><tbody data-product-rows>${productRows(items)}</tbody></table></div>`;}
  function productsPanel(dashboard=false){return `<section class="a-panel"><div class="a-panel-head"><div><h2>${dashboard?'Your collection, at a glance.':'Product library'}</h2><p>${dashboard?'A considered collection. Every detail under your control.':'Create, edit and publish. Your storefront updates in this browser.'}</p></div>${dashboard?`<a href="/preview-admin/?view=products" class="a-text">View all products ${icon('arrow')}</a>`:''}</div>${dashboard?'':`<div class="a-toolbar"><label class="a-search">${icon('search')}<input data-admin-search placeholder="Search product name or SKU…" value="${E(search)}" aria-label="Search products"></label><select data-admin-category aria-label="Filter category"><option value="">All categories</option>${S.state.categories.map(c=>`<option value="${c.id}"${selected(c.id,category)}>${E(c.name)}</option>`).join('')}</select><select data-admin-status aria-label="Filter product status"><option value="">All statuses</option>${['published','draft','archived'].map(v=>`<option${selected(v,filter)}>${v}</option>`).join('')}</select></div>`}${table(dashboard?S.state.products.slice(0,6):filtered())}</section>`;}
  function filtered(){return S.state.products.filter(p=>(!search||[p.name,p.sku].join(' ').toLowerCase().includes(search.toLowerCase()))&&(!filter||p.status===filter)&&(!category||p.collection===category));}
  function dashboard(){return `${metrics()}<div class="a-dashboard-note"><span class="a-note-symbol">K</span><div><strong>A remarkable store starts with the details.</strong><p>Add a watch, choose its category, upload your photographs, and publish.</p></div><button class="a-button gold" data-new-product>${icon('plus')} Add a timepiece</button></div>${productsPanel(true)}<div class="a-lower-grid"><section class="a-panel a-small-panel"><span class="a-label">THE NEXT CHAPTER</span><h2>Make Kairos yours.</h2><p>Set your WhatsApp number, Instagram profile and homepage message in store settings.</p><a class="a-text" href="/preview-admin/?view=settings">Open store settings ${icon('arrow')}</a></section><section class="a-panel a-small-panel"><span class="a-label">A LITTLE CLARITY</span><h2>Your own demo space.</h2><p>Changes and uploaded photos stay in this browser. Other visitors see their own demo. Real orders and customers are handled by the Django application.</p><a class="a-text" href="/shop/">Preview your collection ${icon('arrow')}</a></section></div>`;}
  function categories(){return `<div class="a-category-grid">${S.state.categories.map((c,i)=>`<article class="a-category-card"><div class="a-category-cover"><img src="${E(c.image||'/static/images/hero.webp')}" width="500" height="350" alt="${E(c.name)}"><span>COLLECTION / ${String(i+1).padStart(2,'0')}</span></div><div class="a-category-body"><span class="a-label">${S.state.products.filter(p=>p.collection===c.id).length} PRODUCTS</span><h2>${E(c.name)}</h2><p>${E(c.description||'A collection of considered timepieces.')}</p><div class="a-category-actions">${button(icon('edit')+' Edit category',`data-edit-category="${c.id}"`,'light')}<button class="a-delete-text" data-delete-category="${c.id}" aria-label="Delete ${E(c.name)}">${icon('trash')}</button></div></div></article>`).join('')}</div>`;}
  function orders(){return `<section class="a-panel"><div class="a-panel-head"><div><h2>Sample orders</h2><p>Only local demonstration checkouts appear here. No real customers or payments.</p></div>${button(icon('upload')+' Export CSV','data-export-orders','light')}</div>${S.state.orders.length?`<div class="a-table-scroll"><table class="a-table"><thead><tr><th>Order</th><th>Created</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody>${S.state.orders.map(o=>`<tr><td><strong>${E(o.number)}</strong><small>Demo Customer</small></td><td>${new Date(o.createdAt||Date.now()).toLocaleDateString('en-GB')}</td><td>${o.items.reduce((s,i)=>s+i.qty,0)}</td><td>${money(o.total/100)}</td><td>${o.payment==='bank'?'Bank transfer · unverified':'Cash on delivery · sample'}</td><td><select data-order-status="${E(o.number)}" aria-label="Status for ${E(o.number)}">${['Pending','Confirmed','Processing','Shipped','Delivered','Cancelled'].map(s=>`<option${selected(s,o.status)}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:`<div class="a-empty">${icon('orders')}<h3>Your next chapter awaits.</h3><p>Complete a sample checkout on the storefront to try order management.</p><a href="/shop/" class="a-button">Explore the store ${icon('arrow')}</a></div>`}</section>`;}
  function field(label,name,value='',extra='',type='text'){return `<label class="a-field"><span>${label}</span><input type="${type}" name="${name}" value="${E(value)}" ${extra}></label>`;}
  function settings(){const s=S.state.settings;return `<form data-store-settings class="a-settings"><section class="a-panel a-settings-section"><div class="a-panel-head"><div><span class="a-label">01 / BRAND & FIRST IMPRESSIONS</span><h2>Your storefront, your voice.</h2></div></div><div class="a-form-pad"><div class="a-brand-upload"><img src="${E(s.logo||'/static/images/favicon.svg')}" alt="Store logo" width="80" height="80" data-settings-logo><div><label class="a-button light">${icon('upload')} Change logo<input type="file" accept="image/jpeg,image/png,image/webp" data-logo-upload hidden></label><p>JPG, PNG or WebP. Proportions are preserved.</p><button class="a-text" type="button" data-remove-logo>Use original Kairos mark</button></div></div>${field('Tagline','tagline',s.tagline,'required maxlength="100"')}${field('Announcement bar','announcement',s.announcement,'maxlength="160"')}${field('Hero eyebrow','heroEyebrow',s.heroEyebrow,'maxlength="100"')}<div class="a-form-grid">${field('Hero heading · first line','heroLine1',s.heroLine1,'required maxlength="60"')}${field('Hero heading · second line','heroLine2',s.heroLine2,'required maxlength="60"')}</div><label class="a-field"><span>Hero description</span><textarea name="heroDescription" rows="3" maxlength="250">${E(s.heroDescription)}</textarea></label></div></section><section class="a-panel a-settings-section"><div class="a-panel-head"><div><span class="a-label">02 / CLIENT CONNECTIONS</span><h2>Stay within reach.</h2></div></div><div class="a-form-pad">${field('WhatsApp number · international format','whatsapp',s.whatsapp,'placeholder="923001234567" maxlength="24"')}<p class="a-help">Use your business number. The storefront opens WhatsApp with an enquiry.</p>${field('Instagram · handle or profile URL','instagram',s.instagram,'placeholder="@your_business" maxlength="200"')}${field('Contact email','email',s.email,'placeholder="hello@yourdomain.com" maxlength="150"','email')}<p class="a-help">Empty social links open the contact page until your business details are entered.</p></div></section><div class="a-form-save"><p class="a-form-error" data-settings-error role="alert"></p><button class="a-button gold">${icon('check')} Save store settings</button></div></form><section class="a-panel a-reset-panel"><div><h3>Restore the original demo</h3><p>Reset this browser’s products, categories, settings and sample orders.</p></div>${button('Reset demo','data-reset-demo','danger')}</section>`;}
  const titles={dashboard:['OVERVIEW','Your store. Beautifully in control.','Welcome to your Kairos control room. Every detail, considered.'],products:['CATALOGUE','Your timepieces.','A home for every watch, every finish and every little detail.'],categories:['COLLECTIONS','A place for every style.','Organise your timepieces into thoughtful collections.'],orders:['ORDER MANAGEMENT','Good moments, on their way.','Follow the journey from the first click to the final delivery.'],settings:['STORE SETTINGS','The details that make you.','Your identity, your message and the ways your customers reach you.']};
  function render(){if(!active())return;view=new URLSearchParams(location.search).get('view')||'dashboard';if(!titles[view])view='dashboard';const t=titles[view];document.title=t[1]+' · Kairos Manager';document.body.classList.add('admin-mode');document.querySelector('#main').innerHTML=`<div class="admin-app"><aside class="a-sidebar"><a class="a-brand" href="/preview-admin/"><span class="a-monogram">K</span><span>KAIROS<small>STORE MANAGER</small></span></a><span class="a-nav-label">WORKSPACE</span><nav aria-label="Admin navigation">${['dashboard','products','categories','orders','settings'].map(v=>`<a href="/preview-admin/${v==='dashboard'?'':'?view='+v}" ${v===view?'aria-current="page"':''}>${icon(v)}<span>${v==='products'?'Products':v.charAt(0).toUpperCase()+v.slice(1)}</span>${v==='products'?`<small>${S.state.products.length}</small>`:''}</a>`).join('')}</nav><div class="a-sidebar-bottom"><span class="a-local-dot"></span><strong>Interactive demo</strong><p>Edits stay in your browser.<br>No real orders or payments.</p><a href="/">Visit storefront ${icon('arrow')}</a></div><div class="a-owner"><span>KS</span><div>Kairos Studio<small>Demo workspace</small></div><span>✧</span></div></aside><div class="a-workspace"><header class="a-topbar"><span>Kairos Store <span>/</span> ${view.charAt(0).toUpperCase()+view.slice(1)}</span><div><span class="a-local-pill"><i></i> BROWSER DEMO</span><a href="/shop/" class="a-button light">${icon('eye')} View store</a><span class="a-avatar">K</span></div></header><div class="a-content"><div class="a-page-title"><div><span class="a-label">KAIROS / ${t[0]}</span><h1>${t[1]}</h1><p>${t[2]}</p></div>${['dashboard','products','categories'].includes(view)?button(icon('plus')+(view==='categories'?' Add category':' Add product'),view==='categories'?'data-new-category':'data-new-product','gold'):''}</div><div class="a-demo-banner">${icon('check')}<span>Try everything. Add, edit and delete—your demo changes appear on the storefront in this browser.</span></div>${view==='dashboard'?dashboard():view==='products'?productsPanel():view==='categories'?categories():view==='orders'?orders():settings()}<footer class="a-footer"><span>KAIROS STORE © 2026</span><span>Every Second, Your Style.</span></footer></div></div></div>`;}
  function modal(title,content,kind='product'){let d=document.querySelector('#admin-dialog');if(!d){d=document.createElement('dialog');d.id='admin-dialog';d.className='a-dialog';document.body.append(d);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});}d.classList.toggle('a-dialog-small',kind!=='product');d.innerHTML=`<div class="a-modal-top"><div><span class="a-label">KAIROS / ${kind==='product'?'PRODUCT STUDIO':'STORE MANAGER'}</span><h2>${E(title)}</h2></div><button data-admin-close aria-label="Close dialog">${icon('close')}</button></div>${content}`;if(!d.open)d.showModal();return d;}
  function media(){return `<div class="a-media-grid">${draft.images.map((i,n)=>`<div><img src="${E(i.thumb)}" alt="${E(i.alt)}" width="130" height="150"><span>${n===0?'COVER':'IMAGE '+(n+1)}</span><div><button type="button" data-image-move="${n}" data-direction="-1" aria-label="Move image ${n+1} earlier" ${n===0?'disabled':''}>←</button><button type="button" data-image-move="${n}" data-direction="1" aria-label="Move image ${n+1} later" ${n===draft.images.length-1?'disabled':''}>→</button><button type="button" data-image-remove="${n}" aria-label="Remove image ${n+1}">${icon('trash')}</button></div></div>`).join('')}<label class="a-upload-tile">${icon('plus')}<span>Add photos</span><input type="file" data-product-images accept="image/jpeg,image/png,image/webp" multiple hidden></label></div><p class="a-help">Up to 6 images · JPG, PNG, WebP · 8 MB each. Use arrows to reorder. First image is the cover.</p>`;}
  function variants(){return draft.variants.map((v,i)=>`<div class="a-variant-row" data-variant-row="${i}"><div class="a-variant-title"><strong>VARIANT ${String(i+1).padStart(2,'0')}</strong><button type="button" data-remove-variant="${i}" aria-label="Remove variant ${i+1}" ${draft.variants.length===1?'disabled':''}>${icon('trash')}</button></div><div class="a-form-grid">${field('Finish / variant','variant_name_'+i,v.name,'required maxlength="100"')}${field('SKU','variant_sku_'+i,v.sku,'required maxlength="60"')}${field('Price · PKR','variant_price_'+i,v.price,'required min="0.01" max="99999999" step="0.01"','number')}${field('Stock','variant_stock_'+i,v.stock,'required min="0" max="999999" step="1"','number')}<label class="a-field a-span-two"><span>Variant photograph</span><select name="variant_image_${i}"><option value="">Product gallery</option>${draft.images.map((img,n)=>`<option value="${n}"${selected(v.image,img.thumb)}>Image ${n+1}${n===0?' · cover':''}</option>`).join('')}</select></label></div></div>`).join('');}
  function captureDraft(){const f=document.querySelector('[data-product-form]');if(!f)return;const d=new FormData(f);for(const k of ['name','sku','description','regularPrice','specifications','brandName','strap','movement'])draft[k]=String(d.get(k)||'');draft.collection=String(d.get('collection'));draft.status=String(d.get('status'));draft.featured=d.has('featured');draft.newArrival=d.has('newArrival');draft.price=String(d.get('salePrice')||draft.regularPrice);draft.variants=draft.variants.map((v,i)=>({...v,name:String(d.get('variant_name_'+i)||''),sku:String(d.get('variant_sku_'+i)||''),price:String(d.get('variant_price_'+i)||0),regularPrice:i===0?draft.regularPrice:String(d.get('variant_price_'+i)||0),stock:Number(d.get('variant_stock_'+i)||0),image:d.get('variant_image_'+i)===''?(draft.images[0]?.thumb||'/static/images/product-placeholder.svg'):draft.images[Number(d.get('variant_image_'+i))]?.thumb}));}
  function openProduct(id,refresh=false){if(!refresh){const original=S.state.products.find(p=>p.id===id);draft=original?S.clone(original):{id:Date.now(),name:'',sku:'',collection:S.state.categories[0].id,description:'',specifications:'',regularPrice:'',price:'',brandName:'',brand:'',strap:'',movement:'',stock:0,images:[],variants:[{id:Date.now()*10,name:'Standard',sku:'',price:'',regularPrice:'',stock:0,image:''}],featured:false,newArrival:false,status:'draft',createdAt:new Date().toISOString()};if(!original)draft.url='/product/?id='+draft.id;}
    modal(S.state.products.some(p=>p.id===draft.id)?'Edit your timepiece.':'A new chapter in your collection.',`<form data-product-form><div class="a-editor-layout"><div class="a-editor-main"><section class="a-editor-section"><span class="a-label">01 / THE ESSENTIALS</span><div class="a-form-grid">${field('Product name *','name',draft.name,'required maxlength="120"')}${field('Product SKU *','sku',draft.sku,'required maxlength="60"')}<label class="a-field"><span>Category *</span><select name="collection" required>${S.state.categories.map(c=>`<option value="${c.id}"${selected(draft.collection,c.id)}>${E(c.name)}</option>`).join('')}</select></label>${field('Brand','brandName',draft.brandName,'maxlength="80"')}</div><label class="a-field"><span>Description</span><textarea name="description" rows="3" maxlength="3000">${E(draft.description)}</textarea></label></section><section class="a-editor-section"><span class="a-label">02 / PRICING</span><div class="a-form-grid">${field('Regular price · PKR *','regularPrice',draft.regularPrice,'required min="0.01" max="99999999" step="0.01"','number')}${field('Sale price · optional','salePrice',Number(draft.price)<Number(draft.regularPrice)?draft.price:'','min="0.01" max="99999999" step="0.01"','number')}</div><p class="a-help">The first variant follows your product price. Other variants can have their own prices.</p></section><section class="a-editor-section"><span class="a-label">03 / PHOTOGRAPHY</span><div data-editor-media>${media()}</div><p class="a-upload-message" data-upload-status role="status"></p></section><section class="a-editor-section"><div class="a-section-title"><span class="a-label">04 / VARIANTS & INVENTORY</span><button class="a-text" type="button" data-add-variant>${icon('plus')} Add variant</button></div><div data-editor-variants>${variants()}</div></section><section class="a-editor-section"><span class="a-label">05 / THE DETAILS</span><div class="a-form-grid">${field('Strap material','strap',draft.strap,'maxlength="100"')}${field('Movement','movement',draft.movement,'maxlength="100"')}</div><label class="a-field"><span>Specifications · one detail per line</span><textarea name="specifications" rows="4" maxlength="2000" placeholder="Case size: 40 mm">${E(draft.specifications)}</textarea></label></section></div><aside class="a-editor-aside"><span class="a-label">PUBLISHING</span><label class="a-field"><span>Visibility</span><select name="status">${['draft','published','archived'].map(s=>`<option value="${s}"${selected(s,draft.status)}>${s.charAt(0).toUpperCase()+s.slice(1)}</option>`).join('')}</select></label><p class="a-help">Published products appear automatically in their category on the demo storefront.</p><label class="a-checkbox"><input type="checkbox" name="featured"${draft.featured?' checked':''}> Featured in the Kairos edit</label><label class="a-checkbox"><input type="checkbox" name="newArrival"${draft.newArrival?' checked':''}> Show in new arrivals</label><div class="a-editor-preview"><img data-preview-photo src="${E(draft.images[0]?.thumb||'/static/images/product-placeholder.svg')}" alt="Product card preview" width="220" height="260"><span class="a-label" data-preview-category>${E(S.state.categories.find(c=>c.id===draft.collection)?.name)}</span><h3 data-preview-name>${E(draft.name||'Your next timepiece')}</h3><strong data-preview-price>${money(draft.price||0)}</strong><small>LIVE CARD PREVIEW</small></div></aside></div><div class="a-modal-bottom"><div><p class="a-form-error" data-product-error role="alert"></p><span>Demo changes are saved in this browser.</span></div><div>${button('Cancel','type="button" data-admin-close','light')}<button class="a-button gold">${icon('check')} Save product</button></div></div></form>`);}
  function openCategory(id){categoryDraft=S.clone(S.state.categories.find(c=>c.id===id)||{id:'category-'+Date.now(),name:'',description:'',image:''});modal(id?'Edit category.':'Create a collection.',`<form data-category-form class="a-category-form">${field('Category name *','name',categoryDraft.name,'required maxlength="80"')}<label class="a-field"><span>Description</span><textarea name="description" rows="3" maxlength="300">${E(categoryDraft.description)}</textarea></label><label class="a-category-image"><img src="${E(categoryDraft.image||'/static/images/product-placeholder.svg')}" width="400" height="250" alt="Category photograph" data-category-photo><span class="a-button light">${icon('upload')} Choose photograph</span><input type="file" accept="image/jpeg,image/png,image/webp" data-category-upload hidden></label><p class="a-help">JPG, PNG or WebP · Max 8 MB. New categories appear in the storefront filters and collection section.</p><p class="a-form-error" data-category-error role="alert"></p><div class="a-form-save"><button class="a-button gold">${icon('check')} Save category</button></div></form>`,'category');}
  function confirmDeleteProduct(id){const p=S.state.products.find(p=>p.id===id);modal('Delete this timepiece?',`<div class="a-confirm"><p>“${E(p.name)}” will be removed from this browser’s demo catalogue and storefront.</p><div>${button('Keep product','data-admin-close','light')}${button('Delete product',`data-confirm-delete="${id}"`,'danger')}</div></div>`,'confirm');}
  function downloadCSV(){const rows=[['Order','Date','Items','Total PKR','Payment','Status'],...S.state.orders.map(o=>[o.number,o.createdAt,o.items.reduce((s,i)=>s+i.qty,0),o.total/100,o.payment,o.status])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='kairos-sample-orders.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
  document.addEventListener('click',event=>{const t=event.target.closest('button,a');if(!t)return;const d=document.querySelector('#admin-dialog');
    if(t.hasAttribute('data-admin-close'))d?.close();
    if(t.hasAttribute('data-new-product'))openProduct();if(t.hasAttribute('data-edit-product'))openProduct(Number(t.dataset.editProduct));
    if(t.hasAttribute('data-delete-product'))confirmDeleteProduct(Number(t.dataset.deleteProduct));
    if(t.hasAttribute('data-confirm-delete')){try{S.deleteProduct(Number(t.dataset.confirmDelete));d.close();render();notify('Product deleted from your local demo.');}catch(e){notify(e.message);}}
    if(t.hasAttribute('data-new-category'))openCategory();if(t.hasAttribute('data-edit-category'))openCategory(t.dataset.editCategory);
    if(t.hasAttribute('data-delete-category')){const c=S.state.categories.find(c=>c.id===t.dataset.deleteCategory),count=S.state.products.filter(p=>p.collection===c.id).length;modal('Delete this collection?',`<form data-delete-category-form data-id="${c.id}" class="a-category-form"><p>Remove “${E(c.name)}” from this browser’s demo.</p>${count?`<label class="a-field"><span>Move its ${count} products to</span><select name="reassign" required><option value="">Choose another category</option>${S.state.categories.filter(a=>a.id!==c.id).map(a=>`<option value="${a.id}">${E(a.name)}</option>`).join('')}</select></label>`:''}<p class="a-form-error" data-category-error role="alert"></p><div class="a-form-save"><button class="a-button danger">Delete category</button></div></form>`,'confirm');}
    if(t.hasAttribute('data-add-variant')){captureDraft();if(draft.variants.length>=12){notify('Keep at most 12 demo variants.');return;}draft.variants.push({id:Date.now()*10,name:'',sku:draft.sku+'-'+(draft.variants.length+1),price:draft.price||draft.regularPrice,regularPrice:draft.regularPrice,stock:0,image:draft.images[0]?.thumb||''});openProduct(draft.id,true);}
    if(t.hasAttribute('data-remove-variant')){captureDraft();if(draft.variants.length>1){draft.variants.splice(Number(t.dataset.removeVariant),1);openProduct(draft.id,true);}}
    if(t.hasAttribute('data-image-remove')){captureDraft();draft.images.splice(Number(t.dataset.imageRemove),1);openProduct(draft.id,true);}
    if(t.hasAttribute('data-image-move')){captureDraft();const i=Number(t.dataset.imageMove),j=i+Number(t.dataset.direction);if(j>=0&&j<draft.images.length){[draft.images[i],draft.images[j]]=[draft.images[j],draft.images[i]];openProduct(draft.id,true);}}
    if(t.hasAttribute('data-remove-logo')){event.preventDefault();const f=document.querySelector('[data-store-settings]');f.dataset.logo='';document.querySelector('[data-settings-logo]').src='/static/images/favicon.svg';}
    if(t.hasAttribute('data-reset-demo'))modal('Restore the original demo?',`<div class="a-confirm"><p>This removes this browser’s product edits, uploaded pictures, settings and sample orders.</p><div>${button('Keep my changes','data-admin-close','light')}${button('Restore demo','data-confirm-reset','danger')}</div></div>`,'confirm');
    if(t.hasAttribute('data-confirm-reset')){try{S.reset();localStorage.removeItem('kairos-demo-bag-v1');localStorage.removeItem('kairos-demo-wishlist-v1');localStorage.removeItem('kairos-demo-order-v1');d.close();render();window.KairosUI?.resetShopping();notify('Original demo restored.');}catch(e){notify(e.message);}}
    if(t.hasAttribute('data-export-orders'))downloadCSV();
  });
  document.addEventListener('input',event=>{const t=event.target;if(t.hasAttribute('data-admin-search')){search=t.value;document.querySelector('[data-product-rows]').innerHTML=productRows(filtered());}if(t.closest('[data-product-form]')){const f=t.form;const name=f.elements.namedItem('name').value,price=f.elements.namedItem('salePrice').value||f.elements.namedItem('regularPrice').value;document.querySelector('[data-preview-name]').textContent=name||'Your next timepiece';document.querySelector('[data-preview-price]').textContent=money(price||0);if(t.name==='regularPrice'||t.name==='salePrice'){const v=f.elements.namedItem('variant_price_0');if(v)v.value=price;}if(t.name==='sku'&&draft.variants.length===1){const sku=f.elements.namedItem('variant_sku_0');if(sku&&!S.state.products.some(p=>p.id===draft.id))sku.value=t.value+'-1';}}});
  document.addEventListener('change',async event=>{const t=event.target;
    if(t.hasAttribute('data-admin-status')||t.hasAttribute('data-admin-category')){if(t.hasAttribute('data-admin-status'))filter=t.value;else category=t.value;document.querySelector('[data-product-rows]').innerHTML=productRows(filtered());}
    if(t.hasAttribute('data-order-status')){try{S.updateOrder(t.dataset.orderStatus,t.value);notify('Sample order status updated.');}catch(e){notify(e.message);}}
    if(t.name==='collection'&&t.closest('[data-product-form]'))document.querySelector('[data-preview-category]').textContent=S.state.categories.find(c=>c.id===t.value)?.name||'';
    if(t.hasAttribute('data-product-images')){const status=document.querySelector('[data-upload-status]'),submit=document.querySelector('[data-product-form] button[type=submit], [data-product-form] .a-modal-bottom button:not([type])');try{if(draft.images.length+t.files.length>6)throw Error('Use up to 6 product images.');captureDraft();status.textContent='Optimising your photographs…';if(submit)submit.disabled=true;const processed=[];for(const f of t.files)processed.push(await S.image(f));draft.images.push(...processed);openProduct(draft.id,true);notify('Photographs ready. Save the product to keep them.');}catch(e){status.textContent=e.message;}finally{if(submit)submit.disabled=false;}}
    if(t.hasAttribute('data-category-upload')){try{categoryDraft.image=(await S.image(t.files[0])).medium;document.querySelector('[data-category-photo]').src=categoryDraft.image;}catch(e){document.querySelector('[data-category-error]').textContent=e.message;}}
    if(t.hasAttribute('data-logo-upload')){try{const result=await S.image(t.files[0]);const f=t.closest('form');f.dataset.logo=result.medium;document.querySelector('[data-settings-logo]').src=result.medium;}catch(e){document.querySelector('[data-settings-error]').textContent=e.message;}}
  });
  document.addEventListener('submit',event=>{const f=event.target;if(!f.matches('[data-product-form],[data-category-form],[data-store-settings],[data-delete-category-form]'))return;event.preventDefault();event.stopImmediatePropagation();const data=new FormData(f);try{
    if(f.matches('[data-product-form]')){captureDraft();if(!draft.images.length&&draft.status==='published')throw Error('Add a product photograph before publishing.');draft.variants.forEach(v=>{v.images=draft.images.filter(i=>i.thumb===v.image);if(!v.images.length)v.images=draft.images;});draft.brand=S.slug(draft.brandName);S.saveProduct(draft);document.querySelector('#admin-dialog').close();render();notify('Product saved. View store to see your changes.');}
    if(f.matches('[data-category-form]')){categoryDraft.name=String(data.get('name')).trim();categoryDraft.description=String(data.get('description'));S.saveCategory(categoryDraft);document.querySelector('#admin-dialog').close();render();notify('Category saved to your local demo.');}
    if(f.matches('[data-delete-category-form]')){S.deleteCategory(f.dataset.id,String(data.get('reassign')||''));document.querySelector('#admin-dialog').close();render();notify('Category deleted. Products reassigned.');}
    if(f.matches('[data-store-settings]')){S.saveSettings({...S.state.settings,...Object.fromEntries(data),logo:f.dataset.logo===undefined?S.state.settings.logo:f.dataset.logo});notify('Store settings saved.');}
  }catch(e){const error=f.querySelector('.a-form-error');if(error){error.textContent=e.name==='QuotaExceededError'?'Demo storage is full. Remove a few uploaded images and try again.':e.message;error.scrollIntoView({block:'nearest'});}}});
  window.KairosAdmin={render,active};
})();
